import pytest

from minimum_spanning_tree import minimum_spanning_tree


def _total_weight(edges, weight_by_edge):
    """辅助函数：计算边集合的总权重。"""
    return sum(weight_by_edge[e] for e in edges)


def _is_spanning(edges, weight_by_edge):
    """辅助函数：判断边集合是否连通所有顶点（并查集）。"""
    nodes = set()
    for u, v in weight_by_edge:
        nodes.add(u)
        nodes.add(v)
    if not nodes:
        return True
    parent = {n: n for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    roots = {find(n) for n in nodes}
    return len(roots) == 1


def test_minimum_spanning_tree_docstring_example():
    """docstring 示例图：期望值来自 docstring 明确给出的返回值。"""
    weight_by_edge = {
        (1, 2): 10,
        (2, 3): 15,
        (3, 4): 10,
        (1, 4): 10,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2), (3, 4), (1, 4)}


def test_minimum_spanning_tree_single_edge():
    """单条边图：唯一连通生成树即该边本身。"""
    weight_by_edge = {(1, 2): 5}
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2)}


def test_minimum_spanning_tree_two_edges_shared_vertex():
    """两条边共享顶点：链式图，MST 必须包含两条边。"""
    weight_by_edge = {(1, 2): 3, (2, 3): 4}
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2), (2, 3)}


def test_minimum_spanning_tree_triangle_equal_weights():
    """三角形等权图：MST 不唯一，验证边数为 2 且总权重为 2（数学性质）。"""
    weight_by_edge = {
        (1, 2): 1,
        (2, 3): 1,
        (1, 3): 1,
    }
    result = minimum_spanning_tree(weight_by_edge)
    assert len(result) == 2
    assert _total_weight(result, weight_by_edge) == 2
    assert _is_spanning(result, weight_by_edge)
    assert all(e in weight_by_edge for e in result)


def test_minimum_spanning_tree_zero_weight_edges():
    """权重为 0 的边：排序与选择不受影响，链式图 MST 为两条边。"""
    weight_by_edge = {(1, 2): 0, (2, 3): 0}
    result = minimum_spanning_tree(weight_by_edge)
    assert result == {(1, 2), (2, 3)}


def test_minimum_spanning_tree_negative_weights():
    """负权重边：MST 应包含两条最小权重边，总权重最小（数学性质）。"""
    weight_by_edge = {
        (1, 2): -5,
        (2, 3): -1,
        (1, 3): -3,
    }
