def make_graph(edges):
    """
    根据边字典构建节点对象图。
    edges: dict，键为 (start_name, end_name)，值为边长。
    返回 (length_by_edge, nodes_dict)。
    """
    nodes = {}
    for (a, b) in edges:
        if a not in nodes:
            nodes[a] = Node(a)
        if b not in nodes:
            nodes[b] = Node(b)
    for (a, b), length in edges.items():
        nodes[a].successors.append(nodes[b])
    length_by_edge = {(nodes[a], nodes[b]): length for (a, b), length in edges.items()}
    return length_by_edge, nodes


